import{_ as e,o,c as r,a as n}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const m=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 3 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 3 из 10","date":"2026-10-06T00:00:00.000Z","source":"https://t.me/jfyi_ps/95","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 3 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 3 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 3 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-06\\"}"]]},"headers":[],"relativePath":"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3.md","filePath":"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3.md"}'),i={name:"posts/2026-10-06-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-3.md"};function a(p,t,s,l,c,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026).**</p><ol start="3"><li>Память пользователя и база знаний**</li></ol><p>4 формата факта под разные задачи:</p><ul><li>Simple Notes (некритичные факты),</li><li>Enhanced Notes (повествование, дорого обновлять),</li><li>JSON Cards (частичное обновление),</li><li>Advanced JSON Cards (+backstory/person — для разрешения неоднозначности).</li></ul><p>Запись: ADD-only + ранжирование по релевантности+времени при чтении (Mem0 v3) лучше UPDATE/DELETE на запись (v2) — сохраняет историю, меньше вызовов LLM.</p><p>Многоуровневое сжатие: важность → кластеризация в саммари → абстрагирование в правило. Обезличивай PII локальной моделью, не облаком.</p><p><strong>RAG:</strong> структурный сплит (256-1024 ток, 10-20% перекрытие). Плотный+разреженный (BM25) ретрив вместе — у каждого слепые зоны. Reranker поверх слияния. Метрики recall@k/MRR/nDCG, не на глаз. ANNOY (статично) vs HNSW (динамично).</p><p>Простой top-k недостаточен для агрегаций/границ правил — нужна сводка на индексации. Структурная индексация (RAPTOR — иерархия саммари; GraphRAG — связи/неоднозначность сущностей) — только когда реально нужен синтез/навигация.</p><p>Файловая организация знаний (Markdown+Git): обязательны перекрёстные ссылки и индексные страницы — иначе это нагромождение файлов. 3-уровневая загрузка L0/L1/L2.</p><p>Обновляй базу как репозиторий: PR с Proposer+независимым Reviewer (разные семейства моделей). Периодическая реорганизация: дедупликация, версии с датой устаревания, фильтрация на этапе поиска по правам (не генерации).</p><p>Contextual Retrieval: LLM-префикс с контекстом фрагмента перед векторизацией — усиливает оба типа поиска (-49%/-67% ошибок). Agentic RAG (поиск как инструмент в ReAct) — для сложных многошаговых вопросов. Двухуровневая память (обзор+детали) — путь к проактивности. Риск: knowledge poisoning через найденные документы.</p><p>От себя добавлю: Я разрабатываю kb (<a href="https://github.com/alterfo/kb" target="_blank" rel="noreferrer">https://github.com/alterfo/kb</a>) - базу знаний со всеми известными фичами, Graph of Thoughts/Agentic RAG оказались самыми эффективными способами добиться точных ответов на бенчмарках.</p><p>Продолжение следует...</p>',13)])])}const u=e(i,[["render",a]]);export{m as __pageData,u as default};
